value:
match Mutex.lock t.mutex;
      assert (t.value = None);
      t.value <- (Some a);
      Condition.signal t.cond;
      Condition.wait t.cond t.mutex;
      Mutex.unlock t.mutex
with
| () -> _

(match a with
| { st_dev; st_ino; st_kind; st_perm; st_nlink; st_uid; st_gid; st_rdev;
    st_size; st_atime; st_mtime; st_ctime } -> _)

(match null_stat with
| { st_dev; st_ino; st_kind; st_perm; st_nlink; st_uid; st_gid; st_rdev;
    st_size; st_atime; st_mtime; st_ctime } -> _)

