value:
(match let all_constrs = ref String.Set.empty in
      List.iter
        (fun { pcd_name = { txt = name } } ->
           if String.Set.mem name (!all_constrs)
           then
             raise (Error ((sdecl.ptype_loc), (Duplicate_constructor name)));
           all_constrs := (String.Set.add name (!all_constrs))) scstrs;
      if
        (List.length
           (List.filter (fun cd -> cd.pcd_args <> (Pcstr_tuple [])) scstrs))
          > (Config.max_tag + 1)
      then raise (Error ((sdecl.ptype_loc), Too_many_constructors));
      (let make_cstr scstr =
         let name = Ident.create_local (scstr.pcd_name).txt in
         let (targs, tret_type, args, ret_type) =
           make_constructor env scstr.pcd_loc (Path.Pident id) params
             scstr.pcd_vars scstr.pcd_args scstr.pcd_res in
         let tcstr =
           {
             cd_attributes = (scstr.pcd_attributes);
             cd_loc = (scstr.pcd_loc);
             cd_res = tret_type;
             cd_args = targs;
             cd_vars = (scstr.pcd_vars);
             cd_uid = (Uid.mk ~current_unit:(Env.get_current_unit ()));
             cd_name = (scstr.pcd_name);
             cd_id = name
           } in
         let cstr =
           {
             cd_uid = (tcstr.cd_uid);
             cd_attributes = (scstr.pcd_attributes);
             cd_loc = (scstr.pcd_loc);
             cd_res = ret_type;
             cd_args = args;
             Types.cd_id = name
           } in
         (tcstr, cstr) in
       let make_cstr scstr =
         Builtin_attributes.warning_scope ?ppwarning:None
           scstr.pcd_attributes (fun () -> make_cstr scstr) in
       let rep = if unbox then Variant_unboxed else Variant_regular in
       let (tcstrs, cstrs) = List.split (List.map make_cstr scstrs) in
       ((Ttype_variant tcstrs), (Type_variant (cstrs, rep))))
with
| (_, _) -> _)

