value:
match let ty_res = newgenconstr ty_path decl.type_params in
      let num_consts = ref 0
      and num_nonconsts = ref 0 in
      List.iter
        (fun { cd_args;_} ->
           if cd_args = (Cstr_tuple [])
           then incr num_consts
           else incr num_nonconsts) cstrs;
      (let rec describe_constructors idx_const idx_nonconst =
         function
         | [] -> []
         | { cd_id; cd_args; cd_res; cd_loc; cd_attributes; cd_uid }::rem ->
             let ty_res =
               match cd_res with | Some ty_res' -> ty_res' | None -> ty_res in
             let (tag, descr_rem) =
               match (cd_args, rep) with
               | (_, Variant_unboxed) ->
                   (assert (rem = []); (Cstr_unboxed, []))
               | (Cstr_tuple [], Variant_regular) ->
                   ((Cstr_constant idx_const),
                     (describe_constructors (idx_const + 1) idx_nonconst rem))
               | (_, Variant_regular) ->
                   ((Cstr_block idx_nonconst),
                     (describe_constructors idx_const (idx_nonconst + 1) rem)) in
             let cstr_name = Ident.name cd_id in
             let (existentials, cstr_args, cstr_inlined) =
               let representation =
                 match rep with
                 | Variant_unboxed -> Record_unboxed true
                 | Variant_regular -> Record_inlined idx_nonconst in
               constructor_args ~current_unit decl.type_private cd_args
                 cd_res
                 (let open Path in Pextra_ty (ty_path, (Pcstr_ty cstr_name)))
                 representation in
             let cstr =
               {
                 cstr_uid = cd_uid;
                 cstr_inlined;
                 cstr_attributes = cd_attributes;
                 cstr_loc = cd_loc;
                 cstr_private = (decl.type_private);
                 cstr_generalized = (cd_res <> None);
                 cstr_nonconsts = (!num_nonconsts);
                 cstr_consts = (!num_consts);
                 cstr_tag = tag;
                 cstr_arity = (List.length cstr_args);
                 cstr_args;
                 cstr_existentials = existentials;
                 cstr_res = ty_res;
                 cstr_name
               } in
             (cd_id, cstr) :: descr_rem in
       describe_constructors 0 0 cstrs)
with
| [] -> _
| _::_ -> _

